#include "v32_std.h"
#include <stdio.h>
#define CHECK(x) do{if(!(x)){fprintf(stderr,"V.32 primitive check failed at %d: %s\n",__LINE__,#x);return 1;}}while(0)
static int scrambler(enum v32_std_role role){struct v32_std_scrambler tx,rx;v32_std_scrambler_init(&tx,role);v32_std_scrambler_init(&rx,role);unsigned x=1;for(int i=0;i<10000;i++){x=x*1664525u+1013904223u;int bit=(x>>31)&1,line=v32_std_scramble(&tx,bit),got=v32_std_descramble(&rx,line);if(got!=bit)return 1;}return 0;}
int main(void){CHECK(!scrambler(V32_STD_CALL)&&!scrambler(V32_STD_ANSWER));static const unsigned expected[4][4]={{1,3,0,2},{0,1,2,3},{3,2,1,0},{2,0,3,1}},trellis[4][4]={{0,1,2,3},{1,0,3,2},{2,3,1,0},{3,2,0,1}};for(unsigned q=0;q<4;q++)for(unsigned p=0;p<4;p++){CHECK(v32_std_diff_encode(q,p)==expected[q][p]);CHECK(v32bis_trellis_diff_encode(q,p)==trellis[q][p]);CHECK(v32bis_trellis_diff_decode(trellis[q][p],p)==(int)q);}int a,b,t,bis;uint16_t both=v32_std_rate_word(1,1,0);CHECK(v32_std_rate_decode(both,&a,&b,&t)==0&&a&&b&&!t);CHECK(v32_std_e_word(9600,0)==(uint16_t)(0x888f|(1u<<6)));CHECK(v32_std_rate_decode(v32_std_rate_word(0,0,0),0,0,0)<0);unsigned offered=V32_RATE_4800|V32_RATE_7200|V32_RATE_9600|V32_RATE_12000|V32_RATE_14400,decoded=0;uint16_t rw=v32bis_rate_word(offered,1);CHECK((rw&(1u<<4))&&(rw&(1u<<8))&&(rw&(1u<<12)));CHECK(v32bis_rate_decode(rw,&decoded,&t,&bis)==0&&decoded==offered&&bis);for(int rate=4800;rate<=14400;rate+=2400){uint16_t e=v32bis_e_word(rate,1);int got=0;CHECK(e&&v32bis_e_decode(e,&got,&t,&bis)==0&&got==rate&&bis);}puts("V.32/V.32bis standard primitive tests passed");return 0;}
